project = {"question": "Which region grows fastest?", "data": "orders.csv", "checks": [], "charts": ["growth by region"], "caveats": "six months only"}


def review(project, checklist):
    missing = [item for item in checklist if not project.get(item)]
    return {"missing": missing, "score": int(round((len(checklist) - len(missing)) / len(checklist) * 100))}


print(review(project, ["question", "data", "checks", "charts", "caveats"]))

weights = {"correctness": 3, "explanation": 2, "checks": 3, "pacing": 1}
m1 = {"correctness": 3, "explanation": 3, "checks": 1, "pacing": 3}
m2 = {"correctness": 4, "explanation": 3, "checks": 3, "pacing": 2}
print("up:", [c for c in weights if m2[c] > m1[c]])
print("down:", [c for c in weights if m2[c] < m1[c]])
print("change:", sum(weights[c] * (m2[c] - m1[c]) for c in weights))
